
cc.Class({
    extends: require("LMSlots_Logic_Base"),

    properties: {

    },

    onLoad() {
        this._super();

        let safe_node = cc.find('safe_node', this.node)
        let cfg = cc.vv.gameData.getGameCfg()
        cc.vv.gameData.SetSlotsNode(cc.vv.gameData.GetSlotsScript().node)

        //node pop ui
        let node_pop = cc.find('node_pop_ui', safe_node)
        let script_pop = node_pop.addComponent("Odysseus_Pop")
        script_pop.Init()
        cc.vv.gameData.SetPopNodeScript(script_pop)

        //wheel
        let node_wheel = cc.find('slots/wheelNode', safe_node)
        let script_wheel = node_wheel.addComponent("Odysseus_Wheel_mar")
        script_wheel.Init()
        cc.vv.gameData.SetWheelMarScript(script_wheel)
        node_wheel.active = false;
        
        //pickgame
        let node_pickGame = cc.find('pickGameNode', safe_node)
        let script_pickGame = node_pickGame.addComponent("Odysseus_PickGame")
        script_pickGame.Init()
        cc.vv.gameData.SetPickGameScript(script_pickGame)
    },

});
