//企鹅赏金 pickgame游戏
let Odysseus_Tools = require('./Odysseus_Tools')

cc.Class({
    extends: cc.Component,

    properties: {
        // cc
        _wheelNode: cc.Node,
        _pickGameNode: cc.Node,
        _bagPanel:cc.Node,

        //数据
        _pickBonus: null,
        _wheelItems: [],//转盘items
        _pickItems: [],//pick游戏

        _pickState: 0,//pick游戏状态 0 等待 1 进行中
        _pickIndex: 0,//点到第几个行李箱了

        isOpen: false,//箱子是否是在打开中

        curItemCnt:0,
    },

    onEnable() {
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onRecvMsgSubAction, this);
    },

    onDisable() {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onRecvMsgSubAction, false, this);
    },

    Init() {
        this._wheelItems = []
        let wheelNode = cc.find("wheelGame/wheelNode", this.node)
        this._wheelNode = wheelNode
        let pickGameNode = cc.find("pickGame", this.node)
        this._pickGameNode = pickGameNode

        this._bagPanel = cc.find("panel", this._pickGameNode);

        cc.find("pickGame/downNode", this.node).zIndex = 99

        this._boosterWin = cc.find("Canvas/safe_node/pick_win");
        this._boosterWin.children.forEach(node=>{
            node.active = false;
        })
        // this._boosterWin.active = false;

        let yeNode = cc.find("yeNode", wheelNode)
        for (let index = 1; index <= 10; index++) {
            let cloneNode;
            if (index == 1 || index == 6) {
                cloneNode = cc.instantiate(cc.find("node1", yeNode))
            } else {
                cloneNode = cc.instantiate(cc.find("node2", yeNode))
            }
            cloneNode.active = true
            cloneNode.parent = yeNode
            cloneNode.angle = -(index - 1) * 36
            this._wheelItems.push(cloneNode)
        }

        let handNode = cc.find("handNode", wheelNode)
        Global.btnClickEvent(handNode, function () {
            this.clickHandNode();

        }, this)

        let spine_collect = cc.find("pickGame/spine_collect", this.node)
        let collectBtn = cc.find("pickGame/spine_collect/btn", this.node)
        Global.btnClickEvent(collectBtn, function () {
            this.clickCollectBtn();
        }, this)


    },

    clickHandNode() {
        let handNode = cc.find("wheelGame/wheelNode/handNode", this.node);
        handNode.stopAllActions();
        Global.SlotsSoundMgr.playEffect("pickwheel_spin");

        // 发送51消息
        let req = { c: MsgId.SLOT_SUBGAME_DATA };
        req.gameid = cc.vv.gameData.getGameId()
        req.data = {}
        req.data.rtype = 1
        cc.vv.NetManager.send(req, true);

        handNode.active = false
    },

    clickCollectBtn(){
        let spine_collect = cc.find("pickGame/spine_collect", this.node)
        cc.find("pickGame/spine_collect/btn", this.node).stopAllActions();

        Global.SlotsSoundMgr.playEffect("btn_click");

        /*// 发送51消息
        let req = { c: MsgId.SLOT_SUBGAME_DATA };
        req.gameid = cc.vv.gameData.getGameId()
        req.data = {}
        req.data.rtype = 2
        cc.vv.NetManager.send(req, true);*/

        Odysseus_Tools.nodeAni(spine_collect, 3, () => {
            cc.vv.gameData.GetSlotsScript().ExitPickGame(this._pickBonus)
        })
    },

    //更新转盘上的数字
    updateWheelItems() {
        let wheelItemsData = this._pickBonus.wheelItems
        for (let index = 0; index < wheelItemsData.length; index++) {
            const element = wheelItemsData[index];
            cc.find("lab", this._wheelItems[index]).getComponent(cc.Label).string = element.cnt
        }
    },

    openPickGameNode(pickBonus) {
        this.node.active = true
        this._pickBonus = pickBonus

        cc.find("bg0", this.node).active = false
        cc.find("bg1", this.node).active = false
        cc.find("bg2", this.node).active = false
        cc.find("bg" + pickBonus.level, this.node).active = true

        this._pickGameNode.active = false
        cc.find("wheelGame", this.node).active = false

        if (pickBonus.state === 0) {
            //转盘阶段
            this.updateWheelItems()
            this._wheelNode.angle = 0;
            cc.find("wheelGame", this.node).active = true
            cc.find("wheelGame", this.node).x = 0
            cc.find("handNode", this._wheelNode).active = true
            let self = this;
            cc.vv.gameData.checkAutoPlay(cc.find("handNode", this._wheelNode), function () {
                self.clickHandNode()
            });

            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("pick_wheel_bgm");
        } else {
            //行李箱阶段
            this._pickGameNode.active = true
            this.startPick()
            Global.SlotsSoundMgr.stopBgm();
            if (pickBonus.level > 1) {
                Global.SlotsSoundMgr.playBgm("pick2_bgm");
            } else {
                Global.SlotsSoundMgr.playBgm("pick_bgm");
            }
        }
    },

    onRecvMsgSubAction(msg) {
        if (msg.code === 200) {
            let data = msg.data;
            if (data.errMsg) return;

            if (data.rtype === 1) {
                //转盘结果
                this._pickBonus = data.pickBonus
                this.startMove(data.resultId)
            }
        }
    },

    startMove(resultId) {
        let self = this
        let wheelGame = cc.find("wheelGame", this.node)
        let targetAngle = (resultId - 1) * 36 - 360 * 4
        let targetItem = cc.find("zhuanpan2", self._wheelItems[resultId - 1])

        Global.SlotsSoundMgr.playEffect("pickwheel_roll");

        cc.tween(this._wheelNode)
            .to(9.5, { angle: targetAngle }, { easing: "quadInOut" })
            .call(() => {
                if (targetItem) {
                    targetItem.active = true
                    targetItem.getComponent(sp.Skeleton).setAnimation(0, 'animation2', true)
                }
                Global.SlotsSoundMgr.playEffect("pickwheel_collect");
            })
            .delay(2)
            .call(() => {
                cc.tween(wheelGame)
                    .to(2, { x: 800 })
                    .start()
            })
            .delay(3)
            .call(() => {
                targetItem.active = false
                self.startPick()
            })
            .start()
    },

    //开始pick游戏
    startPick() {
        this._pickGameNode.active = true

        this._pickIndex = this._pickBonus.step ? this._pickBonus.step : 0;

        cc.find("pickGame/downNode", this.node).active = true
        let lab1 = cc.find("downNode/lab1", this._pickGameNode)
        let lab2 = cc.find("downNode/lab2", this._pickGameNode)
        lab1.getComponent(cc.Label).string = this._pickIndex
        lab2.getComponent(cc.Label).string = this._pickBonus.restCnt

        this._pickState = 1
        this._pickItems = []
        this.curItemCnt = 0;
        this.schedule(this.pickGameCallback, 1);
    },

    exitPick() {
        this._pickState = 0
        this._pickIndex = 0
        this.isOpen = false

        this.unschedule(this.pickGameCallback);
        for (const item of this._pickItems) {
            item.removeFromParent()
        }
        cc.find("pickGame/downNode", this.node).active = false

        let items = this._pickBonus.items
        let coinNum = 0
        for (const iterator of items) {
            if (iterator.coin) {
                coinNum += iterator.coin
            } else {
                for (const i of iterator.booster) {
                    coinNum += (i.coin * (iterator.mult || 1))
                }
            }
        }

        Global.SlotsSoundMgr.stopBgm();
        if (this._pickBonus.level == 2) {
            Global.SlotsSoundMgr.playEffect("mega_dialog_collect_show");
        } else if (this._pickBonus.level == 3) {
            Global.SlotsSoundMgr.playEffect("super_dialog_collect_show");
        } else {
            Global.SlotsSoundMgr.playEffect("pick_dialog_collect_show");
        }

        let aniArr = ['2', '3', '1']
        let spine_collect = cc.find("pickGame/spine_collect", this.node)
        let spine = spine_collect.getComponent(sp.Skeleton)
        cc.find("lab", spine_collect).getComponent(cc.Label).string = Global.FormatNumToComma(coinNum)
        spine_collect.active = true
        spine.setAnimation(0, "animation" + aniArr[this._pickBonus.level] + "_1", false)
        spine.addAnimation(0, "animation" + aniArr[this._pickBonus.level] + "_2", true)

        let btn = cc.find("pickGame/spine_collect/btn", this.node);
        cc.vv.gameData.checkAutoPlay(btn,this.clickCollectBtn.bind(this))

    },

    //生成箱子
    async pickGameCallback() {
        if (this._pickItems.length > 10) return;
        for (let index = 0; index < Math.round(Math.random() * (3)/* + 1*/); index++) {

            this.curItemCnt += 1;

            let cloneNode;
            if (this._pickBonus.level === 0) {
                cloneNode = cc.find("pickGame/bagNode1", this.node)
            } else {
                cloneNode = cc.find("pickGame/bagNode2", this.node)
            }

            let bagNode = cc.instantiate(cloneNode)
            bagNode.parent = this._bagPanel
            bagNode.y = this._bagPanel.height/2+bagNode.height //+Math.random()*100
            // bagNode.x = Math.round(Math.random() * (450)) - 200;
            switch (this._pickItems.length % 3) {
                case 0:
                    bagNode.x = -300+Math.random()*100
                    break;
                case 1:
                    bagNode.x = -50+Math.random()*100
                    break;
                case 2:
                    bagNode.x = 300-Math.random()*100
                    break;
                default:
                    break;
            }
            bagNode.isOpen = false
            bagNode.active = true

            Global.btnClickEvent(bagNode, function () {
                this.bagNodeClickFunc(bagNode)
            }, this)

            this._pickItems.push(bagNode)

            if(cc.vv.gameData.isNeedAutoPlay() && this.curItemCnt > 6){
                this.curItemCnt = 0;
                let item = this._pickItems[Global.random(0,this._pickItems.length - 1)];
                item.emit("click", item);
            }

            await cc.vv.gameData.awaitTime(Math.random())
        }
    },

    // 开一个金币箱子动画
    openCoinBag(box, coin){
        let lab = box.getChildByName("lab");
        lab.active = true;
        lab.getComponent(cc.Label).string = Global.formatNumShort(coin);
        let myBet = cc.vv.gameData.GetTotalBet();
        if (coin > myBet * 2) {
            lab.getComponent(cc.Label).font = cc.vv.gameData.GetFontByName("theme234_pick1")
        } else {
            lab.getComponent(cc.Label).font = cc.vv.gameData.GetFontByName("theme234_pick3")
        }
    },

    //单个行李箱点击事件
    async bagNodeClickFunc(btn, data) {
        cc.log("this.isOpen:",this.isOpen)
        if (this.isOpen || this._pickIndex >= this._pickBonus.restCnt) return;
        this.curItemCnt = 0;

        let self = this
        let gameData = cc.vv.gameData

        Global.SlotsSoundMgr.playEffect("pick_open");

        let slotsNode = cc.vv.gameData.GetSlotsNode()
        let item = data ? data : this._pickBonus.items[this._pickIndex]

        btn.isOpen = true
        btn.zIndex = 20
        this.isOpen = true
        this._pickIndex++;
        let lab1 = cc.find("pickGame/downNode/lab1", this.node)
        lab1.getComponent(cc.Label).string = this._pickIndex

        // 发送51消息
        let req = { c: MsgId.SLOT_SUBGAME_DATA };
        req.gameid = cc.vv.gameData.getGameId();
        req.data = {}
        req.data.rtype = 4
        req.data.step = this._pickIndex;
        cc.vv.NetManager.send(req, true);

        if(this._pickIndex == this._pickBonus.restCnt){
            // 发送51消息
            let req = { c: MsgId.SLOT_SUBGAME_DATA };
            req.gameid = cc.vv.gameData.getGameId()
            req.data = {}
            req.data.rtype = 2
            cc.vv.NetManager.send(req, true);
        }

        let spine = btn.getChildByName("spine").getComponent(sp.Skeleton)
        let lab = btn.getChildByName("lab")
        // let lab2 = btn.getChildByName("lab2")
        let dz = btn.getChildByName("qe_dz01");
        let bx = dz.getChildByName("qe_bx01");
        dz.active = false;
        bx.active = false;

        let myBet = gameData.GetTotalBet()

        spine.setAnimation(0, "animation2", false)

        await cc.vv.gameData.awaitTime(0.3);
        if (item.coin) {
            //中金币
            Global.SlotsSoundMgr.playEffect("coin_rollpick");
            this.openCoinBag(btn, item.coin);
            let addCoin = item.coin;
            let haveWin = gameData.GetBottomScript().getCurrentWin();
            gameData.AddCoin(addCoin);
            gameData.GetBottomScript().ShowWin(addCoin + haveWin, 3, haveWin, null, 0.3);
            gameData.GetTopScript().ShowCoin()
        } else if (item.booster) {
            //中多个金币
            Global.SlotsSoundMgr.playEffect("pick_boost");
            dz.active = true;
            dz.getComponent(sp.Skeleton).setAnimation(0,"animation1",false);
            dz.getComponent(sp.Skeleton).addAnimation(0,"animation2",false);
            if(item.mult){
                await cc.vv.gameData.awaitTime(0.5);
                bx.active = true;
                let idx = [2,3,5,8,10].indexOf(item.mult)+1;
                bx.getComponent(sp.Skeleton).setAnimation(0,`animation${idx}`,false);
            }
            await cc.vv.gameData.awaitTime(1.5);

            let boosterlbl = this._boosterWin.getChildByName("lbl");
            let boosterspine = this._boosterWin.getChildByName("pick_zaq01");
            let shoujiEff = this._boosterWin.getChildByName("shouji_1");
            this._boosterWin.active = true;

            let coinTotal = 0;
            for (let i = 0; i < item.booster.length; i++){
                let node = this._pickItems[Global.random(0,this._pickItems.length - 1)];
                if(node == btn || !node.active || node.y > this._bagPanel.height/2 || node.y < -this._bagPanel.height/2){
                    i-=1;
                    continue
                }
                this._pickState = 0;

                // coinTotal += item.booster[i].coin;
                let eff = cc.instantiate(shoujiEff);
                cc.tween(node)
                    .call(()=>{
                        eff.active = true;
                        eff.parent = this._boosterWin;
                        eff.position = this._boosterWin.convertToNodeSpaceAR(btn.convertToWorldSpaceAR(cc.v2(0,0)));
                        eff.getComponent(cc.ParticleSystem).resetSystem();
                        cc.tween(eff)
                            .to(0.5,{position: this._boosterWin.convertToNodeSpaceAR(node.convertToWorldSpaceAR(cc.v2(0,0)))})
                            .start()
                    })
                    .delay(0.5)
                    .call(()=>{
                        eff.active = false;
                        this.openCoinBag(node, item.booster[i].coin);
                    })
                    .delay(2+0.5*i)
                    .call(()=>{
                        let copyLbl = node.getChildByName("lab");
                        let lbl = cc.instantiate(copyLbl);
                        lbl.parent = this._boosterWin;
                        lbl.position = this._boosterWin.convertToNodeSpaceAR(copyLbl.convertToWorldSpaceAR(cc.v2(0,0)));

                        cc.tween(lbl)
                            .to(0.5, {position:cc.v2(0,0)})
                            .call(()=>{
                                boosterlbl.active = true;
                                coinTotal += item.booster[i].coin;
                                boosterlbl.getComponent(cc.Label).string = Global.formatNumShort(coinTotal);
                                if (item.booster[i].coin > myBet * 2) {
                                    boosterlbl.getComponent(cc.Label).font = cc.vv.gameData.GetFontByName("theme234_pick1");
                                } else {
                                    boosterlbl.getComponent(cc.Label).font = cc.vv.gameData.GetFontByName("theme234_pick3");
                                }
                                boosterspine.active = true;
                                boosterspine.getComponent(sp.Skeleton).setAnimation(0,"animation",false);
                                lbl.destroy();
                            })
                            .start()

                        node.active = false;
                        self.initBagNode(node)

                    })
                    .start()
            }

            await cc.vv.gameData.awaitTime(3+item.booster.length*0.5);

            if(item.mult){
                let idx = [2,3,5,8,10].indexOf(item.mult)+1;
                bx.getComponent(sp.Skeleton).setAnimation(0,`animation1${idx}_1`,false);
                cc.tween(bx)
                    .to(0.5,{position:bx.convertToNodeSpaceAR(this._boosterWin.convertToWorldSpaceAR(cc.v2(0,0)))})
                    .start()

                await cc.vv.gameData.awaitTime(0.5);
                boosterlbl.getComponent(cc.Label).string = Global.formatNumShort(coinTotal*item.mult);

            }

            let endNode = cc.vv.gameData.GetBottomScript().getWinLabelNor();
            cc.tween(this._boosterWin)
                .to(0.5, {position:this._boosterWin.convertToNodeSpaceAR(endNode.convertToWorldSpaceAR(cc.v2(0,0)))})
                .call(()=>{
                    this._boosterWin.active = false;
                    this._boosterWin.children.forEach(node=>{
                        node.active = false;
                        this._boosterWin.position = cc.v2(0,0)
                    })
                })
                .start()
            await cc.vv.gameData.awaitTime(0.5)

            // let coinNum = 0
            // for (const i of item.booster) {
            //     console.log("---1coinNum", coinNum, i.coin);
            //     coinNum += i.coin;
            // }
            // coinNum = coinNum * (item.mult || 1)
            //
            // lab.getComponent(cc.Label).string = Global.formatNumShort(coinNum)
            // lab2.getComponent(cc.Label).string = Global.formatNumShort(coinNum)
            // if (coinNum > myBet * 2) {
            //     lab.active = true
            //     lab2.active = false
            // } else {
            //     lab.active = false
            //     lab2.active = true
            // }
            //显示中奖的金币
            let haveWin = gameData.GetBottomScript().getCurrentWin()
            gameData.AddCoin(coinTotal*(item.mult||1))
            gameData.GetBottomScript().ShowWin(coinTotal*(item.mult||1) + haveWin, 3, haveWin, null, 0.3)
            gameData.GetTopScript().ShowCoin()

            this._pickState = 1
        }

        await cc.vv.gameData.awaitTime(0.5);
        self.isOpen = false
        btn.active = false
        self.initBagNode(btn)

        //結束選擇
        if (this._pickIndex === this._pickBonus.restCnt) {
            this.exitPick()
        }
    },

    initBagNode(bagNode) {
        let spine = bagNode.getChildByName("spine").getComponent(sp.Skeleton)
        let lab = bagNode.getChildByName("lab")
        let dz = bagNode.getChildByName("qe_dz01");
        let bx = dz.getChildByName("qe_bx01");

        lab.active = false
        dz.active = false;
        bx.active = false;
        spine.setAnimation(0, "animation1", true)
        bagNode.y = this._bagPanel.height/2+bagNode.height
        bagNode.isOpen = false
        bagNode.active = true
        bagNode.zIndex = 3
        // bagNode.x = Math.round(Math.random() * (450)) - 200;

    },

    update(dt) {
        if (this._pickState != 1) return;
        let speed = 200
        for (const item of this._pickItems) {
            if (!item.isOpen) {
                item.y -= speed * dt
                if (item.y < -(this._bagPanel.height+item.height)/2) {
                    item.y = (this._bagPanel.height+item.height)/2

                    this.curItemCnt += 1;

                    if(cc.vv.gameData.isNeedAutoPlay() && this.curItemCnt > 6){
                        this.curItemCnt = 0;
                        let item = this._pickItems[Global.random(0,this._pickItems.length - 1)];
                        item.emit("click", item);
                    }
                }
            }
        }
    }
});
