let Odysseus_Tools = require('./Odysseus_Tools')
/**
 * 蒙面英雄slots
 * 
 */
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        // cc

        //属性
    },


    onLoad() {
        this._super();
        //监听下注
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, this.onEventTotalbetUpdated, this)

        let unLockNode = cc.find("reels_frame/frameUp/unLockNode", this.node)
        Global.btnClickEvent(unLockNode, () => {
            this.onBtnCollect()
        }, this)
    },

    onEnable() {

    },
    //重写
    StartMove: function () {
        this._super()
        //BGM
        Global.SlotsSoundMgr.playNormalBgm()
    },

    //收到旋转结果
    //gameData模块收到数据后，转发到此处
    onMsgSpine: function (msg) {
        this._gameInfo = msg
        let cards = msg.resultCards
        this.SetSlotsResult(cards)
        this.SetReelStateInfo(cards)
        let multIdxs = msg.multIdxs
        let jackpotInfo = msg.jackpotInfo
        let pickBonus = msg.pickBonus

        if (jackpotInfo) {
            //中了彩金
            Global.SlotsSoundMgr.playEffect("notify");

            cc.find("reels_frame/qipanjili", this.node).active = true
            cc.find("reels_frame/qipanjili", this.node).getComponent(sp.Skeleton).setAnimation(0, "animation", true)
        }

        if (pickBonus) {
            //中了pick游戏
            // Global.SlotsSoundMgr.playEffect("notify2");

            // cc.find("reels_frame/qiejili", this.node).active = true
            // cc.find("reels_frame/qiejili", this.node).getComponent(sp.Skeleton).setAnimation(0, "animation1", false)
            // cc.find("reels_frame/qiejili", this.node).getComponent(sp.Skeleton).setCompleteListener(() => {
            //     cc.find("reels_frame/heidi", this.node).active = false
            // })
            // cc.find("reels_frame/heidi", this.node).active = true
        }

        for (let i = 0; i < this._reels.length; i++) {
            this._reels[i].setBeiShu();
        }
        if (multIdxs) {
            let mi = []
            if (Array.isArray(multIdxs)) { mi = multIdxs}
            //x2 x3 x5 倍数
            for (const item of mi/*multIdxs*/) {
                let symbol = this.GetSymbolByIdx(item.idx)
                symbol.setBeiShu(item.mult)
            }
        }
    },

    //重写：显示bonus中奖
    OnSpinEnd: function () {
        this.onSpinEndAction();
    },

    async onSpinEndAction() {
        cc.find("reels_frame/qipanjili", this.node).active = false
        // cc.find("reels_frame/qiejili", this.node).active = false
        cc.find("reels_frame/heidi", this.node).active = false

        //显示中奖路线
        this.ShowWinTrace()
        //显示底部赢钱
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()) {
            nTotal = cc.vv.gameData.GetGameTotalFreeWin()
        }

        if (this._gameInfo.jackpotInfo) {
            //中了彩金
            this.playJpAni(true)
            Global.SlotsSoundMgr.playEffect("rapid_dialog_collect_show1");

            await new Promise((sucess, failed) => {
                this.CheckJackpotInfo(sucess)
            });
        }

        await new Promise((sucess, failed) => {
            let isUpdate = true
            this.ShowBottomWin(nWin, nTotal, isUpdate, function () {
                sucess()
            });
        });

        if (this._gameInfo.pickBonus) {
            //pick游戏
            await this.CheckPickBonus(this._gameInfo.pickBonus, this._gameInfo.bonusTrail)
        } else if (this._gameInfo.wheelGame) {
            // 获得转盘游戏
            await this.CheckWheelGame(this._gameInfo.wheelGame);
        } else {
            this.CanDoNextRound()
        }

    },

    //触发jp游戏
    async CheckJackpotInfo(sucessFunc) {
        let gameData = cc.vv.gameData
        //展示3s 图标动画
        Global.SlotsSoundMgr.playEffect("symbol_bonus");
        await this.awaitTime(4)
        Global.SlotsSoundMgr.playEffect("bell");
        gameData.GetPopNodeScript().openJpNode(this._gameInfo.jackpotInfo.winCoin, this._gameInfo.jackpotInfo.idxs.length, sucessFunc)
    },

    //触发pick游戏
    async CheckPickBonus(pickBonus, bonusTrail,bReconnect=false) {
        //所有的SYMBOL停止显示动画
        this.stopAllSymbolAni()
        Global.SlotsSoundMgr.playEffect("bell");
        //收集进度条
        if (bonusTrail) {
            this.SetPickGameProgress(bonusTrail.count, true)
        }
        if(!bReconnect){
            //播放pick图标动画
            this.playPickAni(true)
            await this.awaitTime(3);
            this.stopAllSymbolAni()
        }

        Global.SlotsSoundMgr.stopBgm();

        switch (pickBonus.level) {
            case 1:
                Global.SlotsSoundMgr.playEffect("pick_dialog_start_show");
                break;
            case 2:
                Global.SlotsSoundMgr.playEffect("mega_dialog_start_show");
                break;
            case 3:
                Global.SlotsSoundMgr.playEffect("super_dialog_start_show");
                break;
            default:
                break;
        }
        let heidi = cc.find("reels_frame/heidi", this.node)
        let pick_cfNode = cc.find("reels_frame/pick_cf", this.node)
        let mega_cfNode = cc.find("reels_frame/mega_cf", this.node)
        let super_cfNode = cc.find("reels_frame/super_cf", this.node)
        let cdNodeArr = [pick_cfNode, mega_cfNode, super_cfNode]
        cdNodeArr[pickBonus.level].active = true
        heidi.active = true
        cdNodeArr[pickBonus.level].getComponent(sp.Skeleton).setAnimation(0, "animation1", false)
        cdNodeArr[pickBonus.level].getComponent(sp.Skeleton).addAnimation(0, "animation2", false)
        cdNodeArr[pickBonus.level].getComponent(sp.Skeleton).addAnimation(0, "animation3", true)

        await this.awaitTime(3);
        cdNodeArr[pickBonus.level].active = false
        heidi.active = false

        let qiepingNode;
        if (pickBonus.level === 0) {
            Global.SlotsSoundMgr.playEffect("transition_bonus");
            qiepingNode = cc.find("Canvas/safe_node/qieping1")
        } else {
            Global.SlotsSoundMgr.playEffect("transition_super");
            qiepingNode = cc.find("Canvas/safe_node/qieping2")
        }
        qiepingNode.active = true
        qiepingNode.getComponent(sp.Skeleton).setAnimation(0, "animation", false)
        qiepingNode.getComponent(sp.Skeleton).setCompleteListener(()=>{
            qiepingNode.active = false
        })
        await this.awaitTime(1.2);

        cc.vv.gameData.GetPickGameScript().openPickGameNode(pickBonus)
    },

    //退出pick游戏
    async ExitPickGame(pickBonus) {
        let qiepingNode;
        if (pickBonus.level === 0) {
            Global.SlotsSoundMgr.playEffect("transition_bonus");
            qiepingNode = cc.find("Canvas/safe_node/qieping1")
        } else {
            Global.SlotsSoundMgr.playEffect("transition_super");
            qiepingNode = cc.find("Canvas/safe_node/qieping2")
        }
        qiepingNode.active = true
        qiepingNode.getComponent(sp.Skeleton).setAnimation(0, "animation", false)
        await this.awaitTime(1.2);
        cc.find("Canvas/safe_node/pickGameNode").active = false
        let bonusTrail = cc.vv.gameData.getBonusTrail();
        if(bonusTrail.count == bonusTrail.totalCount){
            this.SetPickGameProgress(0);
        }
        await this.awaitTime(1);
        qiepingNode.active = false
        let haveWin = cc.vv.gameData.GetBottomScript().getCurrentWin()
        await cc.vv.gameData.GetSlotsScript().ShowBottomWin(haveWin, haveWin, false, null, 1)
        this.CanDoNextRound()

        //bgm
        Global.SlotsSoundMgr.stopBgm();
        Global.SlotsSoundMgr.playNormalBgm()
    },

    //重写 触发bonus轮盘游戏
    async CheckWheelGame(wheelGame) {
        let gameData = cc.vv.gameData
        //所有的SYMBOL停止显示动画
        this.stopAllSymbolAni()

        //播放bonus图标动画
        this.playWheelAni(true)
        Global.SlotsSoundMgr.playEffect("symbol_bonus");

        await this.awaitTime(1);
        Global.SlotsSoundMgr.playEffect("bell");

        await this.awaitTime(1.5);
        this.playWheelAni(false)

        Global.SlotsSoundMgr.stopBgm();
        Global.SlotsSoundMgr.playEffect("bonus_dialog_start_show");
        let bonus_cfNode = cc.find("reels_frame/bonus_cf", this.node)
        let heidi = cc.find("reels_frame/heidi", this.node)

        bonus_cfNode.active = true
        bonus_cfNode.getComponent(sp.Skeleton).setAnimation(0, 'animation1', false)
        bonus_cfNode.getComponent(sp.Skeleton).addAnimation(0, 'animation2', true)
        heidi.active = true

        await this.awaitTime(3);
        bonus_cfNode.getComponent(sp.Skeleton).addAnimation(0, 'animation3', false)
        await this.awaitTime(1);
        bonus_cfNode.active = false
        heidi.active = false

        Global.SlotsSoundMgr.stopBgm();
        Global.SlotsSoundMgr.playBgm("bonus_bgm");

        //卷轴移动下去
        let reels_bg = cc.find("reels_bg", this.node)
        let reels = cc.find("reels", this.node)
        let reels_frame = cc.find("reels_frame", this.node)
        let top_ani = cc.find("top_ani", this.node)
        reels_bg.runAction(cc.moveTo(0.8, cc.v2(0, -1050)))
        reels.runAction(cc.moveTo(0.8, cc.v2(0, -1050)))
        reels_frame.runAction(cc.moveTo(0.8, cc.v2(0, -1050)))
        top_ani.runAction(cc.moveTo(0.8, cc.v2(0, -1050)))

        //已经中的钱加上去
        if (wheelGame.winCoin > 0) {
            let addCoin = wheelGame.winCoin
            let haveWin = gameData.GetBottomScript().getCurrentWin()
            gameData.AddCoin(addCoin)
            gameData.GetBottomScript().ShowWin(addCoin + haveWin, 3, haveWin, null, 0.3)
            gameData.GetTopScript().ShowCoin()
        }
        await this.awaitTime(0.3);

        let role = cc.find("Canvas/safe_node/role");
        role.getComponent(sp.Skeleton).setAnimation(0,"skill",false);
        await this.awaitTime(0.7);

        //开始转盘游戏
        cc.find("wheelNode", this.node).active = true;
        cc.find("LMSlots_Panel_Click", this.node).active = false;
        // cc.find("role", this.node.parent).active = false;
        cc.vv.gameData.GetWheelMarScript().openWheelGame(true, wheelGame)
        cc.vv.gameData.showOtherSysNode(false);
    },

    // 退出bonus游戏
    async ExitWheelGame() {
        //卷轴移动上去
        let reels_bg = cc.find("reels_bg", this.node)
        let reels = cc.find("reels", this.node)
        let reels_frame = cc.find("reels_frame", this.node)
        let top_ani = cc.find("top_ani", this.node)

        reels_bg.runAction(cc.moveTo(0.8, cc.v2(0, -482)))
        reels.runAction(cc.moveTo(0.8, cc.v2(0, -482)))
        reels_frame.runAction(cc.moveTo(0.8, cc.v2(0, -482)))
        top_ani.runAction(cc.moveTo(0.8, cc.v2(0, -677)))

        cc.vv.gameData.GetWheelMarScript().openWheelGame(false)
        cc.vv.gameData.showOtherSysNode(true);

        //播放bonus图标动画
        await this.awaitTime(0.8);
        this.playWheelAni(true)
        // await this.awaitTime(2);
        cc.find("wheelNode", this.node).active = false;
        cc.find("role", this.node.parent).active = true;
        cc.find("role", this.node.parent).getComponent(sp.Skeleton).setAnimation(0,"idle",true);
        cc.find("LMSlots_Panel_Click", this.node).active = true;
        await this.awaitTime(1);
        let haveWin = cc.vv.gameData.GetBottomScript().getCurrentWin()
        await cc.vv.gameData.GetSlotsScript().ShowBottomWin(haveWin, haveWin, false, null, 1)
        this.CanDoNextRound();

        //bgm
        Global.SlotsSoundMgr.stopBgm();
        Global.SlotsSoundMgr.playNormalBgm()
    },

    //重写
    async ReconnectShow() {
        let gameData = cc.vv.gameData
        let deskInfo = gameData._deskInfo
        this._bottomScript.ShowBtnsByState("moveing_1")

                
        console.log("---1IsPrizePoolLock",gameData.IsPrizePoolLock(0));
        console.log("---1IsPrizePoolLock",gameData.IsPrizePoolLock(1));
        console.log("---1IsPrizePoolLock",gameData.IsPrizePoolLock(2));
        console.log("---1IsPrizePoolLock",gameData.IsPrizePoolLock(3));
        console.log("---1IsPrizePoolLock",gameData.IsPrizePoolLock(4));
        
        gameData.SetWheelItems(deskInfo.wheelItems)
        gameData.GetWheelMarScript().updateWheelItems(deskInfo.wheelItems)
        this.SetPickGameProgress(deskInfo.bonusTrail.count)

        //第一次进游戏弹窗.
        Global.SlotsSoundMgr.playEffect("welcome");

        let tanChuangNode = cc.find("Canvas/safe_node/tanchuang")
        tanChuangNode.active = true
        cc.find("tanchuangSpine", tanChuangNode).getComponent(sp.Skeleton).setAnimation(0, "animation1", false)
        cc.find("tanchuangSpine", tanChuangNode).getComponent(sp.Skeleton).addAnimation(0, "animation2", false)
        let entry = cc.find("tanchuangSpine", tanChuangNode).getComponent(sp.Skeleton).addAnimation(0, "animation3", false)
        await new Promise(succ=>{
            cc.find("tanchuangSpine", tanChuangNode).getComponent(sp.Skeleton).setTrackCompleteListener(entry,() => {
                tanChuangNode.active = false
                succ();
            })
            let btn = cc.find("btn", tanChuangNode);
            Global.btnClickEvent(btn, function () {
                // cc.find("tanchuangSpine", tanChuangNode).getComponent(sp.Skeleton).setAnimation(0, "animation3", false)
                tanChuangNode.active = false
                succ();
            })
        })

        // await this.awaitTime(3)

        //收集默认是开启的
        gameData.SetPickGameState(true)
        this.checkPickEntrance()

        if (deskInfo.pickBonus) {
            //pick游戏
            await this.CheckPickBonus(deskInfo.pickBonus,null,true)
        } else if (deskInfo.wheelGame) {
            // 获得转盘游戏
            await this.CheckWheelGame(deskInfo.wheelGame);
        } else {
            this.CanDoNextRound()
        }
    },

    //下注update
    onEventTotalbetUpdated(data, bInit) {
        let gameData = cc.vv.gameData
        gameData.GetWheelMarScript().updateWheelItems()
        this.checkPickEntrance()
    },

    //检查是否能开启pick 入口
    async checkPickEntrance() {
        let gameData = cc.vv.gameData
        let needBet = gameData.GetOpenPickGameBet()
        let myBet = gameData.GetTotalBet()
        let state = gameData.GetPickGameState()
        let unLockNode = cc.find("reels_frame/frameUp/unLockNode", this.node)
        let spineJiesuo = cc.find("spineJiesuo", unLockNode)
        let spineSs = cc.find("spineSs", unLockNode)
        spineJiesuo.active = false
        spineSs.active = false

        // console.log("---1checkPickEntrance", myBet, needBet, state);
        if (myBet >= needBet && !state) {
            //开
            Global.SlotsSoundMgr.playEffect("collect_unlock");

            gameData.SetPickGameState(true)

            Global.SlotsSoundMgr.playEffect("unlock");
            spineJiesuo.active = true
            cc.find("unLockedNode", unLockNode).active = true
            spineJiesuo.getComponent(sp.Skeleton).setAnimation(0, "animation", false)
            await cc.vv.gameData.awaitTime(0.5);
            spineJiesuo.active = false;
            // // 注册动画的结束回调
            // spineJiesuo.getComponent(sp.Skeleton).setCompleteListener((track) => {
            //     let name = track.animation ? track.animation.name : "";
            //     if (name === "animation") {
            //     }
            // });
        } else if (myBet < needBet && state) {
            //关
            Global.SlotsSoundMgr.playEffect("collect_lock");

            gameData.SetPickGameState(false)

            Global.SlotsSoundMgr.playEffect("lock");
            spineSs.active = true

            cc.find("unLockedNode", unLockNode).active = false
            spineSs.getComponent(sp.Skeleton).setAnimation(0, "animation", false)
            // 注册动画的结束回调
            spineSs.getComponent(sp.Skeleton).setCompleteListener((track) => {
                let name = track.animation ? track.animation.name : "";
                if (name === "animation") {
                    spineSs.getComponent(sp.Skeleton).setAnimation(0, "animation2", false);
                }
            });
        }
    },

    SetPickGameProgress(count, isMove) {
        let gameData = cc.vv.gameData
        let unLockedNode = cc.find("reels_frame/frameUp/unLockNode/unLockedNode", this.node)
        let qieNode = cc.find("qie", unLockedNode)
        qieNode.active = true

        if (count === 0) {
            qieNode.active = false
            // return;
        }
        else {
            if (isMove) {
                Global.SlotsSoundMgr.playEffect("collect_light");
                cc.tween(qieNode)
                    .to(0.5, { x: cc.find("ld" + (count), unLockedNode).x })
                    .start()
            } else {
                qieNode.x = cc.find("ld" + (count), unLockedNode).x
            }
        }

        for (let index = 1; index <= 18; index++) {
            let IdNode = cc.find("ld" + index, unLockedNode)
            let adNode = cc.find("ad" + index, unLockedNode)
            adNode.active = (count) < index
            IdNode.active = (count) >= index
        }

        gameData.SetPickGameProgress(count)
    },

    //点击收集入口按钮
    onBtnCollect() {
        let gameData = cc.vv.gameData
        if (gameData.GetSlotState() !== "idle") {
            return;
        }
        let status = gameData.GetPickGameState()
        let needBet = gameData.GetOpenPickGameBet()
        if (status) {
            //已经解锁收集
            let unLockNode = cc.find("reels_frame/frameUp/unLockNode", this.node)
            cc.find('tipNode', unLockNode).active = true
            cc.find('tipNode', unLockNode).scale = 0
            cc.find('tipNode', unLockNode).stopAllActions()

            cc.tween(cc.find('tipNode', unLockNode))
                .to(0.2, { scale: 1 })
                .delay(2)
                .to(0.2, { scale: 0 })
                .call(() => {
                    cc.find('tipNode', unLockNode).active = false
                    cc.find('tipNode', unLockNode).scale = 1
                })
                .start()
        } else {
            //解锁收集 设置当前押注额
            let unLockLv = gameData.BetToIdx(needBet)
            if (unLockLv) {
                let bottom = gameData.GetBottomScript()
                bottom.SetBetIdx(unLockLv)
                gameData.SetPickGameState(true)
            }
        }
    },

    //停止所有的symbol动画
    stopAllSymbolAni() {
        for (let i = 0; i < this._reels.length; i++) {
            let item = this._reels[i]
            for (let i = 0; i < item._symbols.length; i++) {
                let element = item._symbols[i];
                element.ShowNormal();
                element.ShowKuang(false)
            }
        }
    },

    //symbol 转盘动画
    playWheelAni(isPlay) {
        for (let i = 0; i < this._reels.length; i++) {
            let item = this._reels[i]
            for (let i = 0; i < item._symbols.length; i++) {
                let element = item._symbols[i];
                element.playWheelAnimation(isPlay);
            }
        }
    },

    //symbol pick动画
    playPickAni(isPlay) {
        for (let i = 0; i < this._reels.length; i++) {
            let item = this._reels[i]
            for (let i = 0; i < item._symbols.length; i++) {
                let element = item._symbols[i];
                element.playPickAnimation(isPlay);
            }
        }
    },

    //symbol 奖池动画
    playJpAni(isPlay) {
        for (let i = 0; i < this._reels.length; i++) {
            let item = this._reels[i]
            for (let i = 0; i < item._symbols.length; i++) {
                let element = item._symbols[i];
                element.playJackpotAnimation(isPlay);
            }
        }
    },

    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    },
});
