/**
 * 蒙面英雄的gamedata
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        _slotsNode: null,//slots游戏节点
        isBigStoreToFreeGame: false,//是开启单页玫瑰商店进的免费游戏
        isSmallStoreToFreeGame: false,//是开启玫瑰商店进的免费游戏

    },

    //set nodepopui的脚本
    SetPopNodeScript(scp) {
        this._popupScp = scp
    },

    //get nodepopui的脚本
    GetPopNodeScript(scp) {
        return this._popupScp
    },

    //set slotsNode
    SetSlotsNode(scp) {
        this._slotsNode = scp
    },

    //get slotsNode
    GetSlotsNode(scp) {
        return this._slotsNode
    },

    // 设置游戏的Wheel脚本
    SetWheelMarScript(scp) {
        this._wheelScp = scp
    },

    // 获得游戏的Wheel脚本
    GetWheelMarScript() {
        return this._wheelScp
    },

    // 设置游戏的pickgame脚本
    SetPickGameScript(scp) {
        this._pickGameScp = scp
    },

    // 获得游戏的pickgame脚本
    GetPickGameScript() {
        return this._pickGameScp
    },

    //解锁五种bonus游戏的押注index
    SetJackpotUnlock(JackpotUnlock) {
        this.JackpotUnlock = JackpotUnlock
    },

    GetJackpotUnlock() {
        return this.JackpotUnlock
    },

    //获取开启pick入口下注
    GetOpenPickGameBet() {
        let needBet = this._deskInfo.needBet || 1
        return this._deskInfo.mults[needBet - 1];
    },

    //pick收集条状态
    GetPickGameState() {
        return this.PickGameState
    },

    //设置pick收集条状态
    SetPickGameState(state) {
        this.PickGameState = state
    },

    //pick收集条进度
    GetPickGameProgress() {
        return this.PickGameProgress
    },

    //设置pick收集条进度  最大18  megapick  2 6 10 18
    SetPickGameProgress(num) {
        this.PickGameProgress = num
    },

    //43消息得到的wheelItems
    GetWheelItems() {
        return this.WheelItems
    },

    //43消息得到的wheelItems
    SetWheelItems(WheelItems) {
        this.WheelItems = WheelItems
    },

    
    //将押注等级转换成押注额度
    //押注等级是从1开始，和服务端保持一致
    IdxToBet(idx) {
        return this._deskInfo.mults[idx]
    },

    getBonusTrail() {
        return this._gameInfo ? this._gameInfo.bonusTrail : this._deskInfo.bonusTrail;
    },
});

