
/**蒙面英雄轮盘
 * 
*/
let Odysseus_Tools = require('./Odysseus_Tools')

cc.Class({
    extends: cc.Component,

    properties: {
        //cc
        _yeNode: cc.Node,

        //属性
        _speed: 0,//旋转速度
        _itemAngle: 90,//item 角度
        _type: 1, //类型
        _state: 1,//状态 1待机旋转中 2 wheel游戏中

        _items: [],//item数组
        _itemsData: [],//items data
    },

    Init(type, state) {
        this._yeNode = cc.find("yeNode", this.node)
        this._state = state
        this._type = type
        switch (type) {
            case 1:
                this._itemAngle = 45
                this._speed = 0.1

                break;
            case 2:
                this._itemAngle = 30
                this._speed = 0.2

                break;
            case 3:
                this._itemAngle = 22.5
                this._speed = 0.3

                break;
            default:
                break;
        }
    },

    updateWheelUi(data) {
        let items = data
        let cloneNode;
        this._itemsData = data;
        let GetTotalBet = cc.vv.gameData.GetTotalBet()
        this.node.angle = 0

        for (const iterator of this._items) {
            iterator.removeFromParent()
        }
        this._items = []

        switch (this._type) {
            case 1:
                for (const item of items) {
                    if (item.isEnd) {
                        //end标志
                        cloneNode = cc.instantiate(cc.find('wheel4', this._yeNode))
                    } else if (item.mult || item.coin) {
                        //金币
                        cloneNode = cc.instantiate(cc.find('wheel3', this._yeNode))
                        if (item.coin) {
                            cc.find('lab', cloneNode).getComponent(cc.Label).string = Global.formatNumShort(item.coin)

                        } else {
                            cc.find('lab', cloneNode).getComponent(cc.Label).string = Global.formatNumShort(item.mult * GetTotalBet)
                        }
                    } else if (item.jackpot) {
                        //jp
                        cloneNode = cc.instantiate(cc.find('wheel1', this._yeNode))
                        cc.find('1', cloneNode).active = false
                        cc.find('2', cloneNode).active = false

                        if (cc.find(item.jackpot.id.toString(), cloneNode)) {
                            cc.find(item.jackpot.id.toString(), cloneNode).active = true
                        }

                    } else if (item.boost) {
                        //boost
                        cloneNode = cc.instantiate(cc.find('wheel2', this._yeNode))
                    }
                    cloneNode.x = 0
                    cloneNode.y = 0
                    cloneNode.active = true
                    this._yeNode.addChild(cloneNode)
                    cloneNode.angle = -this._items.length * this._itemAngle
                    this._items.push(cloneNode)
                }
                break;
            case 2:
                for (const item of items) {
                    if (item.isEnd) {
                        //end标志
                        cloneNode = cc.instantiate(cc.find('wheel5', this._yeNode))
                    } else if (item.mult || item.coin) {
                        //金币
                        if (item.color === 0) {
                            cloneNode = cc.instantiate(cc.find('wheel3', this._yeNode))
                        } else {
                            cloneNode = cc.instantiate(cc.find('wheel4', this._yeNode))
                        }
                        if (item.coin) {
                            cc.find('lab', cloneNode).getComponent(cc.Label).string = Global.formatNumShort(item.coin)

                        } else {
                            cc.find('lab', cloneNode).getComponent(cc.Label).string = Global.formatNumShort(item.mult * GetTotalBet)
                        }
                    } else if (item.jackpot) {
                        //jp
                        cloneNode = cc.instantiate(cc.find('wheel1', this._yeNode))
                        cc.find('2', cloneNode).active = false
                        cc.find('3', cloneNode).active = false
                        cc.find('4', cloneNode).active = false

                        if (cc.find(item.jackpot.id.toString(), cloneNode)) {
                            cc.find(item.jackpot.id.toString(), cloneNode).active = true
                        }

                    } else if (item.boost) {
                        //boost
                        cloneNode = cc.instantiate(cc.find('wheel2', this._yeNode))
                    }
                    cloneNode.x = 0
                    cloneNode.y = 0
                    cloneNode.active = true
                    this._yeNode.addChild(cloneNode)
                    cloneNode.angle = -this._items.length * this._itemAngle
                    this._items.push(cloneNode)
                }
                break;
            case 3:
                for (const item of items) {
                    if (item.isEnd) {
                        //end标志
                        cloneNode = cc.instantiate(cc.find('wheel4', this._yeNode))
                    } else if (item.mult || item.coin) {
                        //金币
                        if (item.color === 0) {
                            cloneNode = cc.instantiate(cc.find('wheel3', this._yeNode))
                        } else {
                            cloneNode = cc.instantiate(cc.find('wheel2', this._yeNode))
                        }
                        if (item.coin) {
                            cc.find('lab', cloneNode).getComponent(cc.Label).string = Global.formatNumShort(item.coin)

                        } else {
                            cc.find('lab', cloneNode).getComponent(cc.Label).string = Global.formatNumShort(item.mult * GetTotalBet)
                        }
                    } else if (item.jackpot) {
                        //jp
                        cloneNode = cc.instantiate(cc.find('wheel1', this._yeNode))
                        cc.find('4', cloneNode).active = false
                        cc.find('3', cloneNode).active = false
                        cc.find('5', cloneNode).active = false
                        if (cc.find(item.jackpot.id.toString(), cloneNode)) {
                            cc.find(item.jackpot.id.toString(), cloneNode).active = true
                        }
                    }
                    cloneNode.x = 0
                    cloneNode.y = 0
                    cloneNode.active = true
                    this._yeNode.addChild(cloneNode)
                    cloneNode.angle = -this._items.length * this._itemAngle
                    this._items.push(cloneNode)
                }
                break;
            default:
                break;
        }

    },

    //旋转一次
    startMoveOne(resultId, items) {
        let self = this
        let targetAngle = (resultId - 1) * this._itemAngle - 360 * 4
        let targetItem = cc.find("zhuanpan2", self._items[resultId - 1])

        Global.SlotsSoundMgr.playEffect("wheel_roll");

        console.log("---1resultId", resultId, targetAngle);
        cc.tween(this.node)
            .to(7.8, { angle: targetAngle }, { easing: "quadInOut" })
            .call(() => {
                if (targetItem && !self._itemsData[resultId - 1].isEnd) {
                    targetItem.active = true
                    targetItem.getComponent(sp.Skeleton).setAnimation(0, 'animation' + self._type, true)
                }
            })
            .delay(3)
            .call(() => {
                this.node.angle += 360 * 4;
                if (targetItem) {
                    targetItem.active = false
                }
                self._itemsData = items
                self.endMoveOne(resultId)
            })
            .start()
    },

    //旋转结束
    endMoveOne(resultId) {
        let self = this
        let gameData = cc.vv.gameData
        let data = this._itemsData[resultId - 1]
        let itemNode = this._items[resultId - 1]

        if (data.isEnd) {
            //end结束
            gameData.GetWheelMarScript().endMove()

        } else if (data.coin) {
            //中金币
            Global.SlotsSoundMgr.playEffect("wheel_collect2");

            let addCoin = data.coin
            let haveWin = gameData.GetBottomScript().getCurrentWin()
            gameData.AddCoin(addCoin)
            gameData.GetBottomScript().ShowWin(addCoin + haveWin, 3, haveWin, null, 0.3)
            gameData.GetTopScript().ShowCoin()
            //显示继续点击按钮
            cc.tween(this.node)
                .delay(1)
                .call(() => {
                    if (cc.find("endNode", itemNode)) {
                        cc.find("endNode", itemNode).active = true
                    }
                    gameData.GetWheelMarScript().endMoveOne()
                })
                .start()
        } else if (data.jackpot) {
            //中jp大奖
            Global.SlotsSoundMgr.playEffect("wheel_collect1");

            let addCoin = data.jackpot.value
            let haveWin = gameData.GetBottomScript().getCurrentWin()
            gameData.AddCoin(addCoin)
            gameData.GetBottomScript().ShowWin(addCoin + haveWin, 3, haveWin, null, 0.3)
            gameData.GetTopScript().ShowCoin()
            if (gameData.IsPrizePoolLock(data.jackpot.id - 1)) {
                gameData.GetPopNodeScript().openNormalNode(data.jackpot.value)
            } else {
                gameData.GetPopNodeScript().openWheelJpNode(data.jackpot.id, data.jackpot.value)
            }
            //显示继续点击按钮
            cc.tween(this.node)
                .delay(1)
                .call(() => {
                    if (cc.find("endNode", itemNode)) {
                        cc.find("endNode", itemNode).active = true
                    }
                    gameData.GetWheelMarScript().endMoveOne()
                })
                .start()
        } else if (data.boost) {
            //升级
            Global.SlotsSoundMgr.playEffect("wheel_collect1");
            cc.tween(this.node)
                .delay(2)
                .call(() => {
                    gameData.GetPopNodeScript().openBoost()
                    Global.SlotsSoundMgr.playEffect("boost_dialog_start_show");
                })
                .delay(4)
                .call(() => {
                    if (self._type == 1) {
                        Global.SlotsSoundMgr.playEffect("wheel_fly1");
                    } else {
                        Global.SlotsSoundMgr.playEffect("wheel_fly2");
                    }
                })
                .to(1, { x: 800 })
                .call(() => {
                    gameData.GetWheelMarScript().endMoveOne()
                })
                .start()
        }

    },

    update(dt) {
        if (this._state === 1) {
            this.node.angle -= this._speed * this._itemAngle * dt;
        }
    },

    setState(state) {
        this._state = state
    },

    awaitTime(time) {
        return new Promise((sucess, failed) => {
            this.scheduleOnce(() => {
                sucess()
            }, time);
        });
    },

});
