/**蒙面英雄-符号表 
 * 
*/
let Odysseus_Tools = require('./Odysseus_Tools')

cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {

    },
    //重写
    StartMove: function () {
        this._super()
    },


    //重写 恢复到保存的状态
    Resume(backup) {
        if (!backup) return;
        this._symbolIdx = backup.symbolIdx;
        this._id = backup.id;
        this._data = Global.copy(backup.data);
        this.ShowKuang(backup.isKuang);
        this.ShowNormal();
        let state = backup.state;
        if (state == "win") {
            this.playWinAnimation();
        } else if (state == "stop") {
            this.playStopAnimation();
        } else if (state == "idle") {
            this.playidleAnimation();
        } else if (state == "trigger") {
            this.playTriggerAnimation(true);
        }
    },

    //触发了才播放的。比如已经3个scatter已经触发了免费。这个和中奖的还不一样
    playTriggerAnimation(bPlay) {
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        // console.log("---1trigger动画00000000");
        if (bPlay) {
            // console.log("---1播放trigger动画1222222222",id,cfg.symbol[id],cfg.symbol[id].win_node,cfg.symbol[id].trigger_ani);
            if (cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_ani) {
                this._state = "trigger";
                if (this._showNode) {
                    this._showNode.active = false
                }
                // console.log("---1播放trigger动画13333333");
                let aniNode = this.setAnimationToTop(true)
                aniNode.active = true
                let topShowNode = cc.find(cfg.symbol[id].win_node, aniNode)
                topShowNode.active = true
                if (cfg.symbol[id].trigger_ani.name != "") {
                    aniNode.zIndex = cfg.symbol[id].trigger_ani.zIndex - this._symbolIdx + this._reelIdx * 10;
                    isPlay = true
                    let nodeSp = topShowNode.getComponent(sp.Skeleton)
                    if (nodeSp) {
                        // console.log("---1播放trigger动画4444444444");
                        nodeSp.setAnimation(0, cfg.symbol[id].trigger_ani.name, true)
                    }
                }
            }
        } else {
            this.setAnimationToTop(false);
        }
        return isPlay
    },

    //设置倍数
    setBeiShu(num) {
        let beiShuNode = cc.find("beiShu", this.node)
        if (num) {
            beiShuNode.active = true
            cc.find("2x", beiShuNode).active = false
            cc.find("3x", beiShuNode).active = false
            cc.find("5x", beiShuNode).active = false
            cc.find(num + "x", beiShuNode).active = true
        } else {
            beiShuNode.active = false
        }
    },

    //触发了才播放的。比如已经3个scatter已经触发了免费。这个和中奖的还不一样
    playWheelAnimation(bPlay) {
        let isPlay = false
        let id = this._id
        if (id != 3) return;
        isPlay = this.playTriggerAnimation(bPlay)
        return isPlay
    },

    //触发了才播放的。比如已经3个scatter已经触发了免费。这个和中奖的还不一样
    playPickAnimation(bPlay) {
        let isPlay = false
        let id = this._id
        if (id != 2) return;
        isPlay = this.playTriggerAnimation(bPlay)
        return isPlay
    },

    //奖池ani
    playJackpotAnimation(bPlay) {
        let isPlay = false
        let id = this._id
        if (id != 4) return;
        isPlay = this.playTriggerAnimation(bPlay)
        return isPlay
    },
});
